FILES = {'app/sources/gpb/relevance.py': '"""GPB subject gate v2: explicit non-targets only; no implied LLM approval."""\nimport re\nimport unicodedata\nVERSION = \'gpb-subject-20261019-v2\'\n\n\ndef norm(value):\n    return \' \'.join(unicodedata.normalize(\'NFKC\',str(value or \'\')).casefold().replace(\'ё\',\'е\').split())\n\nPRODUCT = re.compile(r\'\\b(?:лист(?:ы|а|ов|ам|ами|ах)?|лент\\w*|плит\\w*|полос\\w*|труб\\w*|профил\\w*|прут\\w*|шин(?:а|ы|у|ой|ами)?|катанк\\w*|проволок\\w*|фольг\\w*|рулон\\w*|штрипс\\w*|прокат\\w*|поков\\w*|заготов\\w*|слит\\w*|чушк\\w*)\\b\')\nALUMINIUM = re.compile(r\'\\bалюмини\\w*|\\b(?:амг\\s*\\d\\w*|амц\\w*|ад\\s*(?:00|0|1|31|33)\\w*|д(?:1|16|19)\\w*|в95\\w*|вд1\\w*|ак[46](?:[- ]1)?\\w*|а[0567](?:е)?|1561\\w*|1105\\w*)\\b\')\nOTHER_METAL = re.compile(r\'\\b(?:сталь|стали|сталью|сталям\\w*|стальн\\w*|нержав\\w*|сталь20|ст20|ст3|09г2с|12х18н10т|08х18н10|медн\\w*|медь|меди|латун\\w*|бронз\\w*|чугун\\w*)\\b\')\nFINISHED = re.compile(r\'\\b(?:стул(?:а|у|ом|е|ья|ьев|ьям|ьями|ьях)?|стуль\\w*|стол(?:а|у|ом|е|ы|ов|ам|ами|ах)?|кресл\\w*|мебел\\w*|табурет\\w*|диван\\w*|скаме\\w*|шкаф\\w*|светильник\\w*|грабл\\w*|канистр\\w*|перчат\\w*|стремянк\\w*|лестниц\\w*|кастрюл\\w*|сковород\\w*|посуд\\w*|листогибочн\\w*|листоправильн\\w*|станк\\w*|лекарственн\\w*|сульфат\\w*|хлорид\\w*)\\b\')\nSERVICE = re.compile(r\'^(?:(?:право заключения договора на|закупка|поставка|приобретение)\\s+)?(?:выполнени\\w*\\s+работ\\w*|оказани\\w*\\s+услуг\\w*|ремонт\\w*|обслуживани\\w*|монтаж\\w*|демонтаж\\w*|реализаци\\w*|продаж\\w*)\\b\')\n\n\ndef clause_class(value):\n    text=norm(value)\n    # Remove a leading reference, never the words describing the purchased object.\n    text=re.sub(r\'^\\d[\\d/._-]*\\s*[-:.)]?\\s+\',\'\',text)\n    p=PRODUCT.search(text);f=FINISHED.search(text)\n    if SERVICE.search(text):return \'non_target\'\n    if f and (p is None or f.start()<=p.start()):return \'non_target\'\n    if OTHER_METAL.search(text) and not ALUMINIUM.search(text):return \'non_target\'\n    if p and ALUMINIUM.search(text):\n        # E.g. aluminium and steel in one unsplit description needs positions.\n        return \'uncertain\' if OTHER_METAL.search(text) else \'target_product\'\n    return \'uncertain\'\n\n\ndef text_class(value):\n    text=norm(value)\n    parts=re.split(r\';|\\n|\\s+и\\s+|,\\s*(?=(?:стул|кресл|лист|лент|труб|профил|прут|фольг|поставка))\',text)\n    kinds=[clause_class(part) for part in parts if part.strip()]\n    if \'target_product\' in kinds:return \'target_product\'\n    if kinds and all(k==\'non_target\' for k in kinds):return \'non_target\'\n    # Generic tails like "для офиса", kept in the same clause, don\'t rescue furniture.\n    return \'uncertain\'\n\n\ndef screen(item):\n    raw=item.get(\'raw_payload\') or {}\n    positions=raw.get(\'positions\') or []\n    kinds=[];missing=False\n    if isinstance(positions,list):\n        for p in positions:\n            if not isinstance(p,dict):missing=True;continue\n            title=p.get(\'name\') or p.get(\'title\') or p.get(\'product_name\')\n            if not isinstance(title,str) or not title.strip():missing=True;continue\n            kinds.append(text_class(title))\n    state=text_class(item.get(\'title\'))\n    # Public rows may be incomplete: retain uncertainty rather than silently losing a mixed lot.\n    if \'target_product\' in kinds:state=\'target_product\'\n    elif missing or \'uncertain\' in kinds:state=\'uncertain\'\n    elif kinds and all(k==\'non_target\' for k in kinds):\n        state=\'uncertain\' if state==\'target_product\' else \'non_target\'\n    reason={\'non_target\':\'Нецелевой предмет: мебель, готовое изделие, оборудование, работы либо явно неалюминиевый материал.\',\n            \'target_product\':\'Есть признаки алюминиевого материала; спецификация и масса от 500 кг по позиции ещё требуют проверки.\',\n            \'uncertain\':\'Материал или состав закупки не подтверждён; требуется проверить позиции и спецификацию.\'}[state]\n    return {\'version\':VERSION,\'classification\':state,\'action\':\'reject\' if state==\'non_target\' else \'review\',\'reason\':reason}\n\n\ndef blocked_item(item):\n    if item.get(\'source\')!=\'gpb\':return None\n    result=screen(item)\n    if result[\'action\']!=\'reject\':return None\n    return {\'status\':\'skipped\',\'reason\':\'gpb_non_target_subject\',\'external_id\':str(item.get(\'external_id\') or \'\'),\n            \'screening_version\':VERSION,\'details\':result[\'reason\']}\n\n\ndef blocked_tender(tender):\n    if tender is None:return None\n    result=blocked_item({\'source\':tender.source,\'external_id\':tender.external_id,\n                         \'title\':tender.title,\'raw_payload\':tender.raw_payload})\n    if result:result[\'tender_id\']=str(tender.id)\n    return result\n', 'app/sources/gpb/queue_audit.py': '"""Read-only Celery/Redis/GPB backlog audit; never pops, acknowledges or revokes tasks."""\nimport ast\nimport base64\nimport json\nimport sqlite3\nfrom pathlib import Path\nfrom datetime import datetime,timezone\nfrom app.sources.gpb.relevance import screen\n\nLIMIT=10000\nMAX_MESSAGE=16*1024*1024\n\n\ndef decode_message(raw):\n    if isinstance(raw,(bytes,str)):\n        if len(raw)>MAX_MESSAGE:raise ValueError(\'message_size_limit\')\n        raw=json.loads(raw)\n    # Kombu Redis unacked hash stores [message, exchange, routing_key].\n    if isinstance(raw,list) and len(raw)==3 and isinstance(raw[0],dict):raw=raw[0]\n    if not isinstance(raw,dict):raise ValueError(\'unknown_envelope\')\n    h=raw.get(\'headers\') or {}\n    if raw.get(\'content-type\')!=\'application/json\' or h.get(\'compression\'):\n        raise ValueError(\'unsupported_encoding\')\n    body=raw.get(\'body\')\n    if (raw.get(\'properties\') or {}).get(\'body_encoding\')==\'base64\':\n        body=base64.b64decode(body,validate=True)\n    if isinstance(body,(str,bytes)):\n        if len(body)>MAX_MESSAGE:raise ValueError(\'body_size_limit\')\n        body=json.loads(body)\n    if isinstance(body,list) and len(body)>=2:\n        args,kwargs=body[:2]\n    elif isinstance(body,dict):\n        args,kwargs=body.get(\'args\',[]),body.get(\'kwargs\',{})\n    else:raise ValueError(\'unknown_body\')\n    return {\'id\':h.get(\'id\') or raw.get(\'id\'),\'name\':h.get(\'task\') or raw.get(\'task\'),\'args\':args,\'kwargs\':kwargs}\n\n\ndef arguments(value,default):\n    if isinstance(value,str):\n        if len(value)>MAX_MESSAGE:return default\n        try:return ast.literal_eval(value)\n        except (ValueError,SyntaxError,MemoryError,RecursionError):return default\n    return value if isinstance(value,type(default)) or isinstance(value,tuple) else default\n\n\ndef identify(task,by_id,by_external):\n    name=str(task.get(\'name\') or task.get(\'type\') or \'\')\n    args=arguments(task.get(\'args\',[]),[]);kwargs=arguments(task.get(\'kwargs\',{}),{})\n    if not isinstance(kwargs,dict):kwargs={}\n    first=args[0] if args else None\n    incoming=kwargs.get(\'tender_data\',first)\n    if isinstance(incoming,dict) and incoming.get(\'source\')==\'gpb\':\n        return incoming\n    tid=kwargs.get(\'tender_id\')\n    if tid is None and isinstance(first,str) and name.endswith((\'.analyze_tender\',\'.process_tender_documents\')):tid=first\n    if tid is not None:return by_id.get(str(tid))\n    rec=kwargs.get(\'record\',first)\n    if isinstance(rec,dict) and rec.get(\'source\')==\'gpb\':\n        return by_external.get(str(rec.get(\'external_id\'))) or rec\n    return None\n\n\ndef audit():\n    from sqlalchemy import select\n    from app.core.config import settings\n    from app.db.session import SyncSessionLocal\n    from app.models.database import Tender\n    from app.workers.celery_app import celery_app\n    output={\'checked_at\':datetime.now(timezone.utc).isoformat(),\'read_only\':True,\n            \'tasks\':[],\'workers\':{},\'broker\':{},\'backlog\':{},\'errors\':[]}\n    by_id={};by_external={}\n    try:\n        with SyncSessionLocal() as session:\n            rows=session.execute(select(Tender).where(Tender.source==\'gpb\').limit(LIMIT+1)).scalars().all()\n            output[\'db_mapping_complete\']=len(rows)<=LIMIT\n            for t in rows[:LIMIT]:\n                item={\'source\':\'gpb\',\'external_id\':str(t.external_id),\'title\':t.title,\'raw_payload\':t.raw_payload or {},\n                      \'tender_id\':str(t.id),\'analysis_done\':bool(t.analysis_done)}\n                by_id[str(t.id)]=item;by_external[str(t.external_id)]=item\n    except Exception as exc:\n        output[\'errors\'].append({\'phase\':\'db_mapping\',\'type\':type(exc).__name__})\n        output[\'db_mapping_complete\']=False\n    output[\'db_non_target\']=[{\'external_id\':i[\'external_id\'],\'title\':i[\'title\'],\'analysis_done\':i[\'analysis_done\']} for i in by_id.values() if screen(i)[\'action\']==\'reject\']\n    seen=set();unmapped=0\n    def append(task,state):\n        nonlocal unmapped\n        item=identify(task,by_id,by_external)\n        name=str(task.get(\'name\') or task.get(\'type\') or \'\')\n        if item is None:\n            if name.endswith((\'.analyze_tender\',\'.process_tender_documents\')):unmapped+=1\n            return\n        key=(str(task.get(\'id\')),state)\n        if key in seen:return\n        seen.add(key)\n        result=screen(item)\n        output[\'tasks\'].append({\'task_id\':task.get(\'id\'),\'task\':name,\'state\':state,\n            \'external_id\':item.get(\'external_id\'),\'title\':item.get(\'title\'),\n            \'llm_task\':name.endswith(\'.analyze_tender\'),\'classification\':result[\'classification\'],\n            \'blocked_by_new_filter\':result[\'action\']==\'reject\'})\n    names=set()\n    for method in (\'active\',\'reserved\',\'scheduled\',\'active_queues\'):\n        try:\n            data=getattr(celery_app.control.inspect(timeout=3),method)()\n            output[\'workers\'][method]=\'no_response\' if data is None else {k:len(v or []) for k,v in data.items()}\n            for worker,items in (data or {}).items():\n                for item in items or []:\n                    if method==\'active_queues\':\n                        if item.get(\'name\'):names.add(item[\'name\'])\n                    else:append(item.get(\'request\',item),method+\':\'+worker)\n        except Exception as exc:output[\'errors\'].append({\'phase\':method,\'type\':type(exc).__name__})\n    try:\n        with celery_app.connection_for_read() as conn:\n            conn.ensure_connection(max_retries=0)\n            channel=conn.channel()\n            try:\n                if conn.transport.driver_type!=\'redis\':raise ValueError(\'unsupported_broker\')\n                client=channel.client\n                names.update(celery_app.amqp.queues.keys())\n                names.add(celery_app.conf.task_default_queue or \'celery\')\n                names.add(\'discovery\')\n                scanned=0;unknown=0;remaining=0\n                for name in sorted(names):\n                    for priority in channel.priority_steps:\n                        key=channel._q_for_pri(name,priority)\n                        count=client.llen(key);take=min(count,max(0,LIMIT-scanned));remaining+=count-take\n                        for start in range(0,take,50):\n                            for raw in client.lrange(key,start,min(start+49,take-1)):\n                                scanned+=1\n                                try:append(decode_message(raw),\'broker_ready:\'+name)\n                                except (ValueError,TypeError,KeyError):unknown+=1\n                unacked=0\n                for _,raw in client.hscan_iter(channel.unacked_key,count=100):\n                    if unacked>=LIMIT:remaining+=1;break\n                    unacked+=1\n                    try:append(decode_message(raw),\'broker_unacked\')\n                    except (ValueError,TypeError,KeyError):unknown+=1\n                output[\'broker\']={\'ready_scanned\':scanned,\'unacked_scanned\':unacked,\'unread_at_least\':remaining,\n                    \'unparsed\':unknown,\'complete\':remaining==0 and unknown==0,\n                    \'note\':\'Snapshot; messages can move during collection. unacked includes reserved and active.\'}\n            finally:channel.close()\n    except Exception as exc:\n        output[\'broker\']={\'complete\':False,\'error_type\':type(exc).__name__}\n    p=Path(settings.storage_path)/\'gpb_backlog.sqlite3\'\n    if p.exists():\n        try:\n            with sqlite3.connect(p.resolve().as_uri()+\'?mode=ro\',uri=True,timeout=5) as db:\n                total=db.execute(\'SELECT COUNT(*) FROM pending\').fetchone()[0]\n                rows=db.execute(\'SELECT payload FROM pending LIMIT ?\', (LIMIT,)).fetchall()\n            rejected=[]\n            for (payload,) in rows:\n                item=json.loads(payload)\n                if screen(item)[\'action\']==\'reject\':rejected.append({\'external_id\':item.get(\'external_id\'),\'title\':item.get(\'title\')})\n            output[\'backlog\']={\'total\':total,\'checked\':len(rows),\'complete\':total<=LIMIT,\'non_target\':rejected}\n        except Exception as exc:output[\'backlog\']={\'complete\':False,\'error_type\':type(exc).__name__}\n    else:output[\'backlog\']={\'total\':0,\'complete\':True}\n    output[\'unmapped_processing_messages\']=unmapped\n    output[\'note\']=\'No tasks revoked, no queues purged, no DB changes. Running LLM calls are not interrupted.\'\n    print(json.dumps(output,ensure_ascii=False,indent=2,default=str),flush=True)\n    return output\n\nif __name__==\'__main__\':audit()\n'}
PATCHES = [{'path': 'app/sources/eis_freshness.py', 'old': '    from app.reports.review_dismissals import is_dismissed\n', 'new': '    # GPB subject gate: applies to existing queued OCR/LLM tasks too.\n    from app.sources.gpb.relevance import blocked_tender\n    subject_block = blocked_tender(tender)\n    if subject_block:\n        return subject_block\n    from app.reports.review_dismissals import is_dismissed\n'}, {'path': 'app/workers/tasks_parsing.py', 'old': '        source_tender = SourceTender.model_validate(tender_data)\n', 'new': '        source_tender = SourceTender.model_validate(tender_data)\n        from app.sources.gpb.relevance import blocked_item\n        subject_block = blocked_item(source_tender.model_dump())\n        if subject_block:\n            return subject_block\n'}, {'path': 'app/sources/document_preparer.py', 'old': "    if tender.source == 'gpb':\n        from app.sources.gpb.adapter import materialize\n", 'new': "    if tender.source == 'gpb':\n        from app.sources.gpb.relevance import blocked_item\n        if blocked_item(tender.model_dump()):\n            raise ValueError('gpb_non_target_subject')\n        from app.sources.gpb.adapter import materialize\n"}, {'path': 'app/reports/review_dashboard.py', 'old': "            if t.source == 'gpb' and not t.analysis_done:\n", 'new': "            if t.source == 'gpb':\n                # GPB subject v2 also hides previously failed/manual-review records.\n"}, {'path': 'app/reports/review_dashboard.py', 'old': '    for c in list_review_candidates(500):\n', 'new': "    for c in list_review_candidates(500):\n        if c.get('source') == 'gpb':\n            from app.sources.gpb.relevance import screen\n            if screen(c)['action'] == 'reject':\n                continue\n"}]
OLD_RELEVANCE_SHA256 = 'a9cb7f6e1d455dfa2cae81e4f55de62ed2e354ff734f704b3dcf8d01d61ee0b2'
TESTS = "import base64,json\nfrom types import SimpleNamespace\nfrom app.sources.gpb.relevance import screen,blocked_item,blocked_tender\nfrom app.sources.gpb.queue_audit import decode_message,identify\ncases = [\n('Поставка стульев', 'non_target'),('Стулья офисные', 'non_target'),\n('Поставка мебели: стулья и столы', 'non_target'),\n('Поставка стальных предметов','non_target'),('Профиль стальной 09Г2С','non_target'),\n('Лист нержавеющий','non_target'),('Труба медная','non_target'),\n('Поставка листогибочной трехвалковой машины № ТЗ-068','non_target'),\n('Стул с каркасом из алюминиевого профиля','non_target'),\n('Профиль алюминиевый АД31','target_product'),('Поставка листов АМг6','target_product'),\n('Поставка труб алюминиевых','target_product'),('Поставка профиля','uncertain'),\n('Материалы для ЭХЗ','uncertain'),\n('Лист стальной и профиль алюминиевый','target_product'),\n('Поставка стульев и материалов','uncertain'),\n]\nfor title,want in cases:\n got=screen({'title':title})['classification'];assert got==want,(title,got,want)\nassert screen({'title':'Стулья','raw_payload':{'positions':[{'name':'Лист алюминиевый'}]}})['action']=='review'\nassert screen({'title':'Стальные изделия','raw_payload':{'positions':[{}]}})['action']=='review'\nassert blocked_item({'source':'eis','title':'Стулья'}) is None\nobj=SimpleNamespace(source='gpb',external_id='1',id='x',title='Стулья',raw_payload={})\nassert blocked_tender(obj)['reason']=='gpb_non_target_subject'\nfrom app.sources.eis_freshness import gate_saved_tender\nclass Session:\n def get(self,*args):return obj\n def commit(self):raise AssertionError('subject gate must not write DB')\nassert gate_saved_tender(Session(),'x')['reason']=='gpb_non_target_subject'\nbody=json.dumps([['x'],{},{}]).encode()\nenvelope={'headers':{'id':'task','task':'app.workers.tasks_scoring.analyze_tender'},'content-type':'application/json','properties':{'body_encoding':'base64'},'body':base64.b64encode(body).decode()}\nfor raw in [json.dumps(envelope),json.dumps([envelope,'','celery'])]:\n task=decode_message(raw);assert identify(task,{'x':{'source':'gpb','title':'Стулья'}},{})['source']=='gpb'\nenvelope['content-type']='application/x-python-serialize'\ntry:decode_message(envelope)\nexcept ValueError:pass\nelse:raise AssertionError('unsupported encoding accepted')\nprint('GPB_FILTER_REGRESSION_OK: 16 subjects, mixed/unknown positions, non-GPB isolation, saved-task gate, ready/unacked JSON decoding')\n"

import argparse,hashlib,json,os,shutil,subprocess,sys,tempfile
from pathlib import Path
from datetime import datetime,timezone

def prepare(root):
    changes={}
    for rel,text in FILES.items():
        p=root/rel
        if p.exists() and p.read_text()==text:continue
        if p.exists():
            digest=hashlib.sha256(p.read_bytes()).hexdigest()
            if rel.endswith('/relevance.py') and digest==OLD_RELEVANCE_SHA256:pass
            else:raise SystemExit('VERSION_CONFLICT: '+rel+'; no files changed')
        elif rel.endswith('/relevance.py'):
            raise SystemExit('GPB_KEYWORDS_DEPENDENCY_MISSING; no files changed')
        changes[rel]=text
    for e in PATCHES:
        rel=e['path'];p=root/rel
        if not p.is_file():raise SystemExit('MISSING: '+rel)
        text=changes.get(rel,p.read_text())
        if e['new'] in text:continue
        if text.count(e['old'])!=1:raise SystemExit('PATCH_ANCHOR_CONFLICT: '+rel+'; no files changed')
        changes[rel]=text.replace(e['old'],e['new'],1)
    for rel,text in changes.items():compile(text,rel,'exec')
    for rel in ['app/workers/tasks_scoring.py','app/workers/tasks_ocr.py']:
        if 'gate_saved_tender(' not in (root/rel).read_text():raise SystemExit('MISSING_WORKER_GATE: '+rel)
    for rel in ['app/sources/gpb/dispatch.py','app/reports/gpb_dashboard.py','app/marketplace_discovery/primary/gpb_search.py']:
        if 'app.sources.gpb.relevance import screen' not in (root/rel).read_text():raise SystemExit('MISSING_SCREENING_INTEGRATION: '+rel)
    return changes

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check',action='store_true',help='Check compatibility; no changes')
    parser.add_argument('--files-only',action='store_true',help='Development: do not build/restart containers')
    args=parser.parse_args();root=Path.cwd()
    changes=prepare(root)
    print('FILES_TO_UPDATE:',len(changes),flush=True)
    if args.check:return
    if changes:
        backup=Path(tempfile.mkdtemp(prefix='gpb-filter-queue-backup-',dir=root.parent))
        manifest={}
        for rel,text in changes.items():
            p=root/rel;manifest[rel]={'existed':p.exists(),'after_sha256':hashlib.sha256(text.encode()).hexdigest()}
            if p.exists():
                dest=backup/rel;dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,dest)
        (backup/'restore.json').write_text(json.dumps(manifest,indent=2))
        print('BACKUP:',backup,flush=True)
        written=[]
        try:
            for rel,text in changes.items():
                p=root/rel;p.parent.mkdir(parents=True,exist_ok=True)
                fd,tmp=tempfile.mkstemp(dir=p.parent)
                try:
                    with os.fdopen(fd,'w') as f:f.write(text)
                    os.chmod(tmp,p.stat().st_mode & 0o777 if p.exists() else 0o644)
                    os.replace(tmp,p);written.append(rel)
                finally:
                    if os.path.exists(tmp):os.unlink(tmp)
        except Exception:
            for rel in reversed(written):
                if manifest[rel]['existed']:shutil.copy2(backup/rel,root/rel)
                else:(root/rel).unlink(missing_ok=True)
            raise
    if args.files_only:
        print('FILES_ONLY: containers were NOT updated');return
    subprocess.run(['docker','compose','build','app','celery_worker','celery_discovery'],check=True)
    subprocess.run(['docker','compose','run','--rm','--no-deps','-T','celery_discovery','python','-'],input=TESTS,text=True,check=True)
    # Celery warm shutdown: no forced timeout and no SIGKILL of running tasks.
    ids=subprocess.check_output(['docker','compose','ps','-q','celery_worker','celery_discovery'],text=True).split()
    if ids:
        print('Waiting for Celery warm shutdown; running tasks may take time.',flush=True)
        subprocess.run(['docker','kill','--signal=SIGTERM',*ids],check=True)
        subprocess.run(['docker','wait',*ids],check=True)
    subprocess.run(['docker','compose','up','-d','--no-deps','app','celery_worker','celery_discovery'],check=True)
    print('GPB_FILTER_QUEUE_INSTALLED',flush=True)
    print('QUEUE_AUDIT_BEGIN: read-only snapshot; no collection or analysis started',flush=True)
    audit=subprocess.run(['docker','compose','exec','-T','celery_discovery','python','-m','app.sources.gpb.queue_audit'],stdout=subprocess.PIPE,text=True)
    print(audit.stdout,flush=True)
    stamp=datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S')
    report=root/('gpb-queue-audit-'+stamp+'.log');report.write_text(audit.stdout)
    print('QUEUE_AUDIT_REPORT:',report,flush=True)
    if audit.returncode:raise SystemExit('FILTER_INSTALLED_BUT_QUEUE_AUDIT_FAILED; queue state unknown')
    print('No business tasks queued/revoked, no queues purged, no DB edits. Existing analysis history retained.')

if __name__=='__main__':main()
